import React from "react";
import { Carousel, Container, Row, Col, Button } from "react-bootstrap";

function makeSrcSets(base) {
  // base = "img/bg-img/bg-1" (no extension)
  return {
    avif: `${base}-800.avif 800w, ${base}-1200.avif 1200w, ${base}-1600.avif 1600w`,
    webp: `${base}-800.webp 800w, ${base}-1200.webp 1200w, ${base}-1600.webp 1600w`,
    jpgSrc: `${base}-1600.jpg`,
    jpgSrcSet: `${base}-800.jpg 800w, ${base}-1200.jpg 1200w, ${base}-1600.jpg 1600w`,
    smallSvg: `${base}-small.svg`,
  };
}

export default function HeroArea({ onWatchVideo }) {
  return (
    <section id="hero" className="hero-area">
      <Carousel
        fade
        controls
        indicators
        interval={5000}
        className="hero-slides"
      >
        <Carousel.Item>
          <div className="single-hero-slide d-flex align-items-center justify-content-center">
            <figure className="hero-slide-figure">
              <picture>
                {/* AVIF sources (best) */}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-1");
                  return (
                    <source type="image/avif" srcSet={s.avif} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {/* WebP fallback */}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-1");
                  return (
                    <source type="image/webp" srcSet={s.webp} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {/* small SVG placeholder for very small viewports */}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-1");
                  return (
                    <>
                      <source media="(max-width: 600px)" srcSet={s.smallSvg} />
                      <img src={s.jpgSrc} srcSet={s.jpgSrcSet} sizes="(max-width: 600px) 100vw, 1200px" alt="Hero 1" className="img-fluid hero-slide-img" loading="lazy" />
                    </>
                  );
                })()}
              </picture>
            </figure>
            <Container>
              <Row>
                <Col className="text-center">
                  <div className="hero-slides-content">
                    <h6>Latest album</h6>
                    <h2>
                      False Prophets <span>False Prophets</span>
                    </h2>
                    <Button variant="primary" className="mt-3" href="#albums">
                      Discover
                    </Button>
                  </div>
                </Col>
              </Row>
            </Container>
          </div>
        </Carousel.Item>
        <Carousel.Item>
          <div className="single-hero-slide d-flex align-items-center justify-content-center">
            <figure className="hero-slide-figure">
              <picture>
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-images-3");
                  return (
                    <source type="image/avif" srcSet={s.avif} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-images-3");
                  return (
                    <source type="image/webp" srcSet={s.webp} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-images-3");
                  return (
                    <>
                      <source media="(max-width: 600px)" srcSet={s.smallSvg} />
                      <img src={s.jpgSrc} srcSet={s.jpgSrcSet} sizes="(max-width: 600px) 100vw, 1200px" alt="Hero 3" className="img-fluid hero-slide-img" loading="lazy" />
                    </>
                  );
                })()}
              </picture>
            </figure>
            <Container>
              <Row>
                <Col className="text-center">
                  <div className="hero-slides-content">
                    <h6>On Tour</h6>
                    <h2>
                      Catch Us Live <span>On the Road</span>
                    </h2>
                    <Button variant="primary" className="mt-3" href="#shows">
                      See Shows
                    </Button>
                  </div>
                </Col>
              </Row>
            </Container>
          </div>
        </Carousel.Item>

        <Carousel.Item>
          <div className="single-hero-slide d-flex align-items-center justify-content-center">
            <figure className="hero-slide-figure">
              <picture>
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-2");
                  return (
                    <source type="image/avif" srcSet={s.avif} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-2");
                  return (
                    <source type="image/webp" srcSet={s.webp} sizes="(max-width: 600px) 100vw, 1200px" />
                  );
                })()}
                {(() => {
                  const s = makeSrcSets("img/bg-img/bg-2");
                  return (
                    <>
                      <source media="(max-width: 600px)" srcSet={s.smallSvg} />
                      <img src={s.jpgSrc} srcSet={s.jpgSrcSet} sizes="(max-width: 600px) 100vw, 1200px" alt="Hero 2" className="img-fluid hero-slide-img" loading="lazy" />
                    </>
                  );
                })()}
              </picture>
            </figure>
            <Container>
              <Row>
                <Col className="text-center">
                  <div className="hero-slides-content">
                    <h6>Latest Video</h6>
                    <h2>
                      El Muerte <span>El Muerte </span>
                    </h2>
                    <Button
                      variant="primary"
                      className="mt-3"
                      onClick={() =>
                        onWatchVideo &&
                        onWatchVideo(
                          "https://www.youtube.com/embed/OFdPTWqJsns?autoplay=1"
                        )
                      }
                    >
                      Watch Video
                    </Button>
                  </div>
                </Col>
              </Row>
            </Container>
          </div>
        </Carousel.Item>
      </Carousel>
    </section>
  );
}
